import{_ as o,o as t,c as r,a0 as a}from"./chunks/framework.DQOulFGV.js";const p=JSON.parse('{"title":"Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md"}'),n={name:"en/guide/faq.md"};function s(i,e,d,l,h,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;Frequently Asked Questions (FAQ)&quot;">​</a></h1><p>Common questions and troubleshooting guides for KernelEX.</p><hr><h3 id="q1-why-do-top-htop-or-vim-look-broken-in-the-terminal" tabindex="-1">Q1: Why do <code>top</code>, <code>htop</code>, or <code>vim</code> look broken in the terminal? <a class="header-anchor" href="#q1-why-do-top-htop-or-vim-look-broken-in-the-terminal" aria-label="Permalink to &quot;Q1: Why do `top`, `htop`, or `vim` look broken in the terminal?&quot;">​</a></h3><p><strong>A</strong>: KernelEX is a pipe-based GUI executor (<code>stdin</code> / <code>stdout</code> / <code>stderr</code> redirection) rather than a full PTY (pseudo-terminal) emulator. Full-screen ncurses applications that require cursor repositioning cannot render properly. KernelEX is optimized for automation scripts, background daemons, and system module flashing.</p><hr><h3 id="q2-why-are-binary-programs-named-so" tabindex="-1">Q2: Why are binary programs named <code>.so</code>? <a class="header-anchor" href="#q2-why-are-binary-programs-named-so" aria-label="Permalink to &quot;Q2: Why are binary programs named `.so`?&quot;">​</a></h3><p><strong>A</strong>: In Android environments, executable binary permissions are restricted. Naming ELF executables with <code>.so</code> is a widely adopted convention across Magisk modules and rooting tools. KernelEX executes <code>.so</code> files directly with automatic <code>chmod 777</code>.</p><hr><h3 id="q3-why-does-my-background-script-get-killed-by-the-os" tabindex="-1">Q3: Why does my background script get killed by the OS? <a class="header-anchor" href="#q3-why-does-my-background-script-get-killed-by-the-os" aria-label="Permalink to &quot;Q3: Why does my background script get killed by the OS?&quot;">​</a></h3><p><strong>A</strong>:</p><ol><li>Go to &quot;Settings&quot; or the Permission Gate and tap <strong>&quot;Request Ignore Battery Optimization&quot;</strong> to add KernelEX to the battery whitelist.</li><li>In customized OEM skins (HyperOS, OriginOS, ColorOS), remember to <strong>lock</strong> KernelEX in the recent tasks overview and allow auto-start permissions.</li></ol><hr><h3 id="q4-how-do-i-restore-the-default-font" tabindex="-1">Q4: How do I restore the default font? <a class="header-anchor" href="#q4-how-do-i-restore-the-default-font" aria-label="Permalink to &quot;Q4: How do I restore the default font?&quot;">​</a></h3><p><strong>A</strong>: Open the &quot;Settings&quot; tab, locate the &quot;Custom Font&quot; card, tap the gear icon, and tap <strong>&quot;Restore Default Font&quot;</strong> to instantly reset to the built-in typeface.</p><hr><h3 id="q5-what-is-the-purpose-of-independent-folder-storage" tabindex="-1">Q5: What is the purpose of &quot;Independent Folder Storage&quot;? <a class="header-anchor" href="#q5-what-is-the-purpose-of-independent-folder-storage" aria-label="Permalink to &quot;Q5: What is the purpose of &quot;Independent Folder Storage&quot;?&quot;">​</a></h3><p><strong>A</strong>: When multiple scripts contain companion files with identical names (like <code>config.json</code>), putting them all into <code>/data/adb/KernelEX/</code> would cause overwrites. Independent folders isolate each script into its own <code>[name]_[timestamp]</code> subdirectory.</p>',18)])])}const m=o(n,[["render",s]]);export{p as __pageData,m as default};
